import{_ as t,o,c as i,a3 as a}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse('{"title":"Estimates Module","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Estimates Module | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/estimates-overview"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Estimates Module | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/estimates-overview"}]]},"headers":[],"relativePath":"user-guide/estimates-overview.md","filePath":"user-guide/estimates-overview.md","lastUpdated":1787321193000}'),s={name:"user-guide/estimates-overview.md"};function n(r,e,d,c,l,m){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="estimates-module" tabindex="-1">Estimates Module <a class="header-anchor" href="#estimates-module" aria-label="Permalink to &quot;Estimates Module&quot;">​</a></h1><p>Tenant customer-billing module on the frozen platform — the fourth Phase 3 (Billing) module, shipped alongside <a href="/user-guide/invoices-overview">Invoices</a>, <a href="/user-guide/payments-overview">Payments</a>, and <a href="/user-guide/credit-notes-overview">Credit Notes</a>. Lets a tenant issue pre-sale cost estimates to a contact/company, optionally tied to an Opportunity or Quotation, and <strong>convert</strong> an accepted estimate straight into a draft <a href="/user-guide/invoices-overview">Invoice</a>.</p><p><strong>Hard dependency on Invoices.</strong> Like Payments and Credit Notes, Estimates declares a <strong>required</strong> <code>module_dependencies</code> row on Invoices — a workspace must have Invoices installed before Estimates can be enabled from Marketplace (the conversion action always needs a place to create the resulting invoice).</p><h2 id="guides" tabindex="-1">Guides <a class="header-anchor" href="#guides" aria-label="Permalink to &quot;Guides&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Audience</th><th>Document</th></tr></thead><tbody><tr><td>Operators / workspace users</td><td><a href="/user-guide/estimates">estimates.md</a></td></tr><tr><td>Engineers</td><td><a href="/developer-guide/estimates">estimates.md</a></td></tr><tr><td>Production / ops</td><td><a href="/deployment/estimates">estimates.md</a></td></tr><tr><td>Module Development Standard</td><td><a href="/developer-guide/module-development">module-development.md</a></td></tr><tr><td>Reference blueprint</td><td><a href="/user-guide/quotations-overview">quotations-overview.md</a>, <a href="/user-guide/invoices-overview">invoices-overview.md</a></td></tr><tr><td>Tenant API</td><td><a href="/api/tenant-v1-estimates">../api/tenant-v1-estimates.md</a></td></tr></tbody></table><h2 id="capabilities" tabindex="-1">Capabilities <a class="header-anchor" href="#capabilities" aria-label="Permalink to &quot;Capabilities&quot;">​</a></h2><ul><li>Estimate fields: title, optional contact/company link, optional opportunity/quotation link, currency, valid-until date, notes</li><li>Auto-numbered (<code>EST-00001</code>; prefix backed by the <code>estimates_number_prefix</code> tenant setting, default <code>EST-</code> — not yet exposed in the Tenant Settings UI)</li><li>Line items (description, quantity, unit price, tax rate) — subtotal / tax total / total computed server-side, same pattern as Invoices/Quotations</li><li>Status workflow: <code>draft → sent → accepted | rejected | expired</code> (<code>POST /estimates/{id}/send</code>, <code>.../accept</code>, <code>.../status</code>)</li><li><strong>Convert to invoice</strong> (<code>POST /estimates/{id}/convert</code>) — creates a draft <code>CustomerInvoice</code> with the estimate&#39;s lines, links it back via <code>estimate_id</code>, and marks the estimate <strong>Accepted</strong> if it wasn&#39;t already. One-way and one-time per estimate. Blocked if the linked quotation is already invoiced.</li><li>Assignment with assignee scoping via <code>estimates.assign</code></li><li>Notes + domain activity timeline (mirrors Invoices/Quotations)</li><li>Trash filtering plus <strong>Restore</strong> and <strong>Delete permanently</strong></li><li>Module licensing (<code>module:estimates</code>) + Spatie permissions — <strong>free Marketplace opt-in</strong> (Billing category), <strong>requires Invoices</strong></li><li>Audit + activity logging; assignment notification</li></ul><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p><code>estimates.view</code> · <code>create</code> · <code>update</code> · <code>delete</code> · <code>restore</code> · <code>force.delete</code> · <code>assign</code> · <code>send</code> · <code>accept</code> · <code>convert</code></p><p>Enable Estimates from Marketplace (free) — <strong>Invoices must already be installed</strong>; Marketplace blocks the install otherwise. Catalog: slug <code>estimates</code>, category <code>billing</code>, <code>is_default_included = false</code>, <code>is_billable = false</code>, <code>sort_order = 40</code>.</p><h2 id="related-modules" tabindex="-1">Related modules <a class="header-anchor" href="#related-modules" aria-label="Permalink to &quot;Related modules&quot;">​</a></h2><p><strong>Required:</strong> <a href="/user-guide/invoices-overview">Invoices</a> — Estimates cannot be installed, or converted, without it. <strong>Optional:</strong> Contacts, Companies, Opportunities, and Quotations (pickers only appear/validate when entitled). See <a href="/architecture/module-dependencies">Module Dependencies</a>.</p><h2 id="explicitly-deferred" tabindex="-1">Explicitly deferred <a class="header-anchor" href="#explicitly-deferred" aria-label="Permalink to &quot;Explicitly deferred&quot;">​</a></h2><ul><li>Estimate PDF export / e-mail delivery to the customer</li><li>Re-converting or reversing a converted estimate (conversion is one-way, one-time)</li><li>Multi-currency conversion</li><li>Approval workflow beyond the status enum</li></ul>',14)])])}const g=t(s,[["render",n]]);export{p as __pageData,g as default};
